import {PERMISSIONS,ROLE_PERMISSIONS,DEPENDS,registerMember,updateMember,removeMember} from './shared/team-state.js?v=5.8.0';
import {teamRead,teamChange,SAMPLE_STORAGE} from './shared/team-storage.js?v=5.8.0';
import {expansionCopy} from './shared/expansion-copy.js?v=5.8.0';
import {brandMark} from './shared/brand.js?v=5.6.0';
import {esc,icon} from './shared/core.js?v=5.6.0';
import {formatDateTime} from './shared/locale.js?v=5.6.0';
const link=(id,lang)=>new URL(`staff.html?lang=${lang}&member=${encodeURIComponent(id)}`,location.href).href;
const permissions=(list,c)=>PERMISSIONS.map(p=>`<label><input type="checkbox" name="permission" value="${p}" ${list.includes(p)?'checked':''}><span>${esc(c[p])}</span></label>`).join('');
export function teamMarkup(lang,enabled=true){const c=expansionCopy(lang);if(!enabled)return `<section class="team-panel"><h1>${esc(c.team)}</h1><p>${esc(c.demoBoundary)}</p><a class="button" href="owner.html?lang=${lang}#team">${esc(c.openTeam)}</a></section>`;const s=teamRead();return `<section class="team-panel" id="team-panel"><header class="team-heading">${brandMark('greeting',true)}<div><small>${esc(c.superAdmin)}</small><h1>${esc(c.team)}</h1><p>${esc(c.teamIntro)}</p></div></header><p class="team-boundary">${esc(c.demoBoundary)}</p><div class="team-roles"><div><h3>${esc(c.floor)}</h3><p>${esc(c.floorNote)}</p><a href="staff.html?lang=${lang}&role=floor" target="_blank" rel="noopener">${esc(c.rolePreview)} ${icon('arrow')}</a></div><div><h3>${esc(c.kitchen)}</h3><p>${esc(c.kitchenNote)}</p><a href="staff.html?lang=${lang}&role=kitchen" target="_blank" rel="noopener">${esc(c.rolePreview)} ${icon('arrow')}</a></div></div><form data-team-register><h2>${esc(c.register)}</h2><div class="team-form-row"><label>${esc(c.memberName)}<input name="name" maxlength="30" required autocomplete="off"></label><label>${esc(c.role)}<select name="role" data-team-role>${['floor','kitchen','custom'].map(r=>`<option value="${r}">${esc(c[r])}</option>`).join('')}</select></label></div><fieldset class="team-permissions"><legend>${esc(c.permissions)}</legend>${permissions(ROLE_PERMISSIONS.floor,c)}</fieldset><button class="button primary" type="submit">${esc(c.register)}</button></form><p class="team-feedback" role="status" aria-live="polite"></p><p class="team-hint">${esc(c.staffHint)}</p><div class="team-members">${s.teamMembers.map(m=>`<article class="team-member"><header><div><h2>${esc(m.name)}</h2><small>${esc(c[m.role])}</small></div><a class="button" href="${esc(link(m.id,lang))}" target="_blank" rel="noopener">${esc(c.invite)}${icon('arrow')}</a></header><form data-team-edit="${m.id}"><fieldset class="team-permissions"><legend>${esc(c.permissions)}</legend>${permissions(m.permissions,c)}</fieldset><div class="team-actions"><button class="button" type="submit">${esc(c.save)}</button><button class="button" type="button" data-team-copy="${m.id}">${esc(c.copyInvite)}</button><button class="button danger" type="button" data-team-remove="${m.id}">${esc(c.remove)}</button></div></form><details class="team-link"><summary>${esc(c.invite)}</summary><a href="${esc(link(m.id,lang))}" target="_blank" rel="noopener">${esc(link(m.id,lang))}</a></details></article>`).join('')}</div><aside class="team-policy"><h2>${esc(c.ownerOnly)}</h2><p>${esc(c.productionLogic)}</p></aside><section class="team-audit"><h2>${esc(c.audit)}</h2>${s.teamAudit.length?s.teamAudit.slice(0,8).map(a=>`<p><b>${esc(a.actor==='owner'?c.superAdmin:a.actor)}</b><span>${esc(auditLabel(a.action,c))} · ${esc(a.target)}</span><small>${esc(formatDateTime(a.at,lang))}</small></p>`).join(''):`<p>${esc(c.emptyAudit)}</p>`}</section></section>`;}
function auditLabel(action,c){return ({register:c.register,permissions:c.permissions,remove:c.remove,menu:c.menuEdit,settings:c.settingsEdit,booking:c.bookingAccept,'order:accepted':c.ordersAccept,'order:preparing':c.ordersPrepare,'order:ready':c.ordersPrepare,'order:completed':c.ordersServe})[action]||action;}
export function bindTeam(host,lang,refresh){if(!host)return ()=>{};const c=expansionCopy(lang);let removing=null;const note=text=>{const el=host.querySelector('.team-feedback');if(el){el.textContent=text;el.scrollIntoView({block:'nearest'});}};const run=fn=>{try{fn();refresh();const el=document.querySelector('.team-feedback');if(el)el.textContent=c.saved;}catch(e){note(c[e.message]||c.noAccess);}};
 const submit=e=>{const form=e.target;if(!form.matches('[data-team-register],[data-team-edit]'))return;e.preventDefault();const data=new FormData(form);run(()=>teamChange(s=>form.hasAttribute('data-team-register')?registerMember(s,'owner',{name:data.get('name'),role:data.get('role'),permissions:data.getAll('permission')}):updateMember(s,'owner',form.dataset.teamEdit,data.getAll('permission'))));};
 const change=e=>{if(e.target.matches('[data-team-role]')){const form=e.target.form;form.querySelectorAll('[name=permission]').forEach(x=>x.checked=ROLE_PERMISSIONS[e.target.value].includes(x.value));}if(e.target.name==='permission'){const form=e.target.form,inputs=[...form.querySelectorAll('[name=permission]')];if(e.target.checked&&DEPENDS[e.target.value])inputs.find(x=>x.value===DEPENDS[e.target.value]).checked=true;if(!e.target.checked)inputs.filter(x=>DEPENDS[x.value]===e.target.value).forEach(x=>x.checked=false);}};
 const click=async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.teamCopy){try{await navigator.clipboard.writeText(link(b.dataset.teamCopy,lang));note(c.copied);}catch{note(c.linkUnavailable);}}if(b.dataset.teamRemove){if(removing!==b.dataset.teamRemove){removing=b.dataset.teamRemove;b.textContent=c.removeConfirm;note(c.removeNote);return;}run(()=>teamChange(s=>removeMember(s,'owner',removing)));removing=null;}};
 const storage=e=>{if(e.key===SAMPLE_STORAGE)refresh();};host.addEventListener('submit',submit);host.addEventListener('change',change);host.addEventListener('click',click);window.addEventListener('storage',storage);return ()=>{host.removeEventListener('submit',submit);host.removeEventListener('change',change);host.removeEventListener('click',click);window.removeEventListener('storage',storage);};}
export function teamBook(lang){const c=expansionCopy(lang);return `<section class="book-team" id="team-access"><header>${brandMark('greeting',true)}<div><h3>${esc(c.teamLead)}</h3><p>${esc(c.teamIntro)}</p></div></header><div class="team-book-roles"><article><h4>${esc(c.superAdmin)}</h4><p>${esc(c.ownerOnly)}</p></article><article><h4>${esc(c.floor)}</h4><p>${esc(c.floorNote)}</p></article><article><h4>${esc(c.kitchen)}</h4><p>${esc(c.kitchenNote)}</p></article></div><div class="team-book-logic"><p>${esc(c.productionLogic)}</p><p>${esc(c.alternative)}</p></div><div class="cover-actions"><a class="button primary" href="jumo/owner.html?lang=${lang}#team" target="_blank" rel="noopener">${esc(c.openTeam)}${icon('arrow')}</a><a class="button secondary" href="jumo/staff.html?lang=${lang}&role=floor" target="_blank" rel="noopener">${esc(c.floor)}</a><a class="button secondary" href="jumo/staff.html?lang=${lang}&role=kitchen" target="_blank" rel="noopener">${esc(c.kitchen)}</a></div><p class="team-hint">${esc(c.demoBoundary)}</p></section>`;}
